138	{
139	    int i;
140	    for(i = 0; i < DISK_PAGE_NUM; i++){
141	        if(disk_page[i].valid == 0){
142	            break;
143	        }
144	    }
145	    assert(i != DISK_PAGE_NUM);
146	    disk_page[i].valid = 1;
147	
148	    sbi_sd_write((unsigned int)pa, PAGE_SD_BLOCKS, SWAP_BEGIN + i * PAGE_SD_BLOCKS);
149	
150	    /* Remember where the page went inside its own page table entry: the
151	     * frame number field now holds the swap slot and _PAGE_SOFT marks the
152	     * entry as "on disk" so that the page fault handler can tell it apart
153	     * from a never-mapped address. */
154	    PTE *pgtable = user_page[pa2num(pa)].pgtable;
155	    if(pgtable != NULL){
156	        clear_attribute(pgtable, _PAGE_PRESENT);
157	        set_attribute(pgtable, _PAGE_SOFT);
158	        set_pfn(pgtable, (uint64_t)i);
