192	    for(int vpn2 = NUM_PTE_ENTRY / 2; vpn2 < NUM_PTE_ENTRY; vpn2++){
193	        pgdir_kva[vpn2] = kernel_pgdir_kva[vpn2];
194	    }
195	
196	    /* the program image and the first page of the user stack */
197	    for(uintptr_t va = USER_CODE_BEGIN; va < USER_CODE_END; va += PAGE_SIZE){
198	        alloc_page_helper(va, (uintptr_t)pgdir);
199	    }
200	    alloc_page_helper(USER_STACK_ADDR - PAGE_SIZE, (uintptr_t)pgdir);
201	
202	    return pgdir;
203	}
204	
205	void free_process_user_page(PTE* pgdir)
206	{
207	    if(pgdir == NULL || (uintptr_t)pgdir == PGDIR_PA){
208	        return;
209	    }
210	
211	    PTE *pgdir_kva = (PTE*)pa2kva((uintptr_t)pgdir);
212	
213	    /* Only the user half is owned by this process; VPN2 >= 0x100 belongs to
214	     * the kernel, which is shared by everybody. */
215	    for(int vpn2 = 0; vpn2 < NUM_PTE_ENTRY / 2; vpn2++){
216	        if(!get_attribute(pgdir_kva[vpn2], _PAGE_PRESENT)){
217	            continue;
218	        }
219	        uintptr_t second_pa = get_pa(pgdir_kva[vpn2]);
220	        PTE *second_kva = (PTE*)pa2kva(second_pa);
221	
222	        for(int vpn1 = 0; vpn1 < NUM_PTE_ENTRY; vpn1++){
223	            if(!get_attribute(second_kva[vpn1], _PAGE_PRESENT)){
224	                continue;
225	            }
226	            uintptr_t third_pa = get_pa(second_kva[vpn1]);
227	            PTE *third_kva = (PTE*)pa2kva(third_pa);
228	
229	            for(int vpn0 = 0; vpn0 < NUM_PTE_ENTRY; vpn0++){
230	                PTE leaf = third_kva[vpn0];
231	                if(leaf == 0){
232	                    continue;
233	                }
234	                if(get_attribute(leaf, _PAGE_PRESENT)){
235	                    uintptr_t pa = get_pa(leaf);
236	                    int shared = 0;
237	                    /* a shared page only goes away with its last user */
238	                    for(int k = 0; k < SHM_PAGE_NUM; k++){
239	                        if(shm_page[k].count > 0 && shm_page[k].pa == pa){
240	                            shm_page[k].count--;
241	                            if(shm_page[k].count == 0){
242	                                free_user_page(pa);
243	                                shm_page[k].pa = 0;
244	                            }
245	                            shared = 1;
246	                            break;
247	                        }
248	                    }
249	                    if(!shared){
250	                        free_user_page(pa);
251	                    }
252	                }
253	                else if(get_attribute(leaf, _PAGE_SOFT)){
254	                    /* the page was swapped out, give the disk slot back */
255	                    disk_page[get_pfn(leaf)].valid = 0;
256	                }
257	                third_kva[vpn0] = 0;
258	            }
259	
260	            free_pgdir_page(third_pa);
261	            second_kva[vpn1] = 0;
262	        }
263	
264	        free_pgdir_page(second_pa);
265	        pgdir_kva[vpn2] = 0;
266	    }
267	
268	    free_pgdir_page((uintptr_t)pgdir);
269	    local_flush_tlb_all();
270	}
271	
272	/* Walk the three levels of `pgdir` (a pa) down to the leaf entry for `va`,
273	 * creating the intermediate tables on the way. Returns a pointer to the leaf
274	 * PTE, which the caller reaches through the kernel's direct mapping. */
275	static PTE* walk_pgdir(uintptr_t va, uintptr_t pgdir)
276	{
277	    uint64_t vpn[3];
278	    vpn[2] = (va >> VPN2_SHIFT) & VPN_MASK;
279	    vpn[1] = (va >> VPN1_SHIFT) & VPN_MASK;
280	    vpn[0] = (va >> VPN0_SHIFT) & VPN_MASK;
281	
282	    PTE *table = (PTE*)pa2kva(pgdir);
283	    for(int level = 2; level > 0; level--){
284	        PTE *entry = table + vpn[level];
285	        if(!get_attribute(*entry, _PAGE_PRESENT)){
286	            PTE *next = alloc_pgdir_page();
287	            *entry = 0;
288	            set_pfn(entry, (uintptr_t)next >> NORMAL_PAGE_SHIFT);
289	            /* a pointer entry carries no R/W/X bits */
290	            set_attribute(entry, _PAGE_PRESENT);
291	        }
292	        table = (PTE*)pa2kva(get_pa(*entry));
293	    }
294	    return table + vpn[0];
295	}
296	
297	/* Same walk, but without creating anything: returns NULL when the address is
298	 * not backed by a leaf entry at all. */
299	static PTE* find_pte(uintptr_t va, uintptr_t pgdir)
300	{
301	    uint64_t vpn[3];
302	    vpn[2] = (va >> VPN2_SHIFT) & VPN_MASK;
303	    vpn[1] = (va >> VPN1_SHIFT) & VPN_MASK;
304	    vpn[0] = (va >> VPN0_SHIFT) & VPN_MASK;
305	
306	    PTE *table = (PTE*)pa2kva(pgdir);
307	    for(int level = 2; level > 0; level--){
308	        PTE *entry = table + vpn[level];
309	        if(!get_attribute(*entry, _PAGE_PRESENT)){
310	            return NULL;
311	        }
312	        table = (PTE*)pa2kva(get_pa(*entry));
313	    }
314	    return table + vpn[0];
315	}
316	
317	/*
318	 * Make sure `va` is backed by a physical frame in `pgdir` (a pa) and return
319	 * the kernel virtual address of that frame.  A page that had been swapped out
320	 * is read back from the SD card first.  The signature matches the callback
321	 * load_elf() expects, so it doubles as the "prepare page" hook of do_exec().
322	 */
323	// pgdir is pa. if va is not mapped, then mapped it
324	uintptr_t alloc_page_helper(uintptr_t va, uintptr_t pgdir)
325	{
326	    va = ROUNDDOWN(va, PAGE_SIZE);
327	    PTE *pte = walk_pgdir(va, pgdir);
328	
329	    if(!get_attribute(*pte, _PAGE_PRESENT)){
330	        if(get_attribute(*pte, _PAGE_SOFT)){
331	            /* the page lives in the swap area, fetch it back */
332	            uint64_t slot = get_pfn(*pte);
333	            uintptr_t pa = alloc_user_page(0, pte);
334	            sbi_sd_read((unsigned int)pa, PAGE_SD_BLOCKS, SWAP_BEGIN + slot * PAGE_SD_BLOCKS);
335	            disk_page[slot].valid = 0;
336	            *pte = 0;
337	            set_pfn(pte, pa >> NORMAL_PAGE_SHIFT);
338	        }
339	        else{
340	            uintptr_t pa = alloc_user_page(0, pte);
341	            *pte = 0;
342	            set_pfn(pte, pa >> NORMAL_PAGE_SHIFT);
343	        }
344	        set_attribute(pte, _PAGE_PRESENT | _PAGE_READ | _PAGE_WRITE | _PAGE_EXEC |
345	                           _PAGE_USER | _PAGE_ACCESSED | _PAGE_DIRTY);
346	        local_flush_tlb_all();
347	    }
348	
349	    return pa2kva(get_pa(*pte));
350	}
351	
352	uintptr_t shm_page_get(int key)
353	{
354	    shm_page_t *page = &shm_page[(uint32_t)key % SHM_PAGE_NUM];
355	
356	    if(page->count == 0){
357	        /* first user of this key: give the group a pinned frame, it must
358	         * never be swapped out behind the back of the other sharers */
359	        page->pa = alloc_user_page(1, NULL);
360	    }
361	
362	    uintptr_t pgdir = (uintptr_t)current_running[cpu_id]->pgdir;
363	    for(uintptr_t va = SHM_VA_BEGIN; va < SHM_VA_END; va += PAGE_SIZE){
364	        PTE *pte = walk_pgdir(va, pgdir);
365	        if(get_attribute(*pte, _PAGE_PRESENT) || get_attribute(*pte, _PAGE_SOFT)){
366	            continue;
367	        }
368	        *pte = 0;
369	        set_pfn(pte, page->pa >> NORMAL_PAGE_SHIFT);
370	        set_attribute(pte, _PAGE_PRESENT | _PAGE_READ | _PAGE_WRITE |
371	                           _PAGE_USER | _PAGE_ACCESSED | _PAGE_DIRTY);
372	        page->count++;
373	        local_flush_tlb_all();
374	        return va;
375	    }
376	
377	    /* the share window of this process is full */
378	    if(page->count == 0){
379	        free_user_page(page->pa);
380	        page->pa = 0;
381	    }
382	    return 0;
383	}
384	
385	void shm_page_dt(uintptr_t addr)
386	{
387	    uintptr_t pgdir = (uintptr_t)current_running[cpu_id]->pgdir;
388	    PTE *pte = find_pte(ROUNDDOWN(addr, PAGE_SIZE), pgdir);
389	
390	    if(pte == NULL || !get_attribute(*pte, _PAGE_PRESENT)){
391	        return;
392	    }
393	
394	    /* only a page that really belongs to a share group may be detached,
395	     * otherwise a bogus address would silently unmap private memory */
396	    uintptr_t pa = get_pa(*pte);
397	    for(int i = 0; i < SHM_PAGE_NUM; i++){
398	        if(shm_page[i].count > 0 && shm_page[i].pa == pa){
399	            *pte = 0;
400	            local_flush_tlb_all();
401	
402	            shm_page[i].count--;
403	            if(shm_page[i].count == 0){
404	                free_user_page(pa);
405	                shm_page[i].pa = 0;
406	            }
407	            return;
408	        }
409	    }
410	}
411	
412	void handle_page_fault(regs_context_t *regs, uint64_t stval, uint64_t cause)
413	{
414	    /* Anything outside the user half of the Sv39 address space is a genuine
415	     * kernel bug; let the generic handler dump the context. */
416	    if(stval >= (1lu << (VPN2_SHIFT + PPN_BITS - 1))){
417	        handle_other(regs, stval, cause);
418	        return;
419	    }
420	
421	    /* demand paging: give the faulting address a frame (or fetch it back
422	     * from the swap area) and let the instruction run again */
423	    alloc_page_helper(stval, (uintptr_t)current_running[cpu_id]->pgdir);
424	}

