/* The two maps are plain bit vectors, one bit per object, least significant
 * bit first.  They are small enough (512B and 32KB) to keep a whole copy in
 * the cache and rewrite it after every change, which keeps the on-disk state
 * consistent without a journal. */
static int map_test(volatile uintptr_t map, uint64_t idx)
{
    volatile uint8_t *bytes = (volatile uint8_t*)map;
    return (bytes[idx / 8] >> (idx % 8)) & 1;
}

static void map_set(volatile uintptr_t map, uint64_t idx)
{
    volatile uint8_t *bytes = (volatile uint8_t*)map;
    bytes[idx / 8] |= (uint8_t)(1u << (idx % 8));
}

static void map_clear(volatile uintptr_t map, uint64_t idx)
{
    volatile uint8_t *bytes = (volatile uint8_t*)map;
    bytes[idx / 8] &= (uint8_t)~(1u << (idx % 8));
}

// Returns inode id
uint16_t alloc_inode()
{
    read_superblock();
    read_inodemap();

    uint64_t total = superblock->inode_num;
    for(uint64_t i = 0; i < total; i++){
        if(map_test(inodemap, i)){
            continue;
        }
        map_set(inodemap, i);
        write_inodemap();

        superblock->used_inode_num = superblock->used_inode_num + 1;
        write_superblock();
        return (uint16_t)i;
    }

    /* no free inode left */
    return 0xffff;
}

// Returns block id
uint32_t alloc_block()
{
    read_superblock();
    read_blockmap();

    uint64_t total = superblock->block_num;
    for(uint64_t i = 0; i < total; i++){
        if(map_test(blockmap, i)){
            continue;
        }
        map_set(blockmap, i);
        write_blockmap();

        superblock->used_block_num = superblock->used_block_num + 1;
        write_superblock();
        return (uint32_t)i;
    }

    /* no free block left */
    return 0xffffffff;
}

void free_inode(uint16_t inode_id)
{
    read_superblock();
    if(inode_id >= superblock->inode_num){
        return;
    }

    read_inodemap();
    if(!map_test(inodemap, inode_id)){
        /* already free, do not let used_inode_num drift */
        return;
    }
    map_clear(inodemap, inode_id);
    write_inodemap();

    superblock->used_inode_num = superblock->used_inode_num - 1;
    write_superblock();
}

void free_block(uint32_t block_id)
{
    read_superblock();
    if(block_id >= superblock->block_num){
        return;
    }

    read_blockmap();
    if(!map_test(blockmap, block_id)){
        return;
    }
    map_clear(blockmap, block_id);
    write_blockmap();

    superblock->used_block_num = superblock->used_block_num - 1;
    write_superblock();
}

