#include <os/fs.h>
#include <os/disk.h>
#include <os/mm.h>
#include <os/sched.h>
#include <os/irq.h>
#include <os/string.h>
#include <os/stdio.h>

volatile superblock_t* superblock = SUPERBLOCK_CACHE;
volatile uintptr_t blockmap = BLOCKMAP_CACHE;
volatile uintptr_t inodemap = INODEMAP_CACHE;
volatile uintptr_t cached_inode_base = INODE_CACHE;
volatile uintptr_t cached_block_base = BLOCK_CACHE;
volatile uint16_t cached_inode_id;
volatile uint32_t cached_block_id;

uint16_t current_dir_inode;
uint32_t current_dir_block;

/* Block 0 belongs to the root directory from the moment the file system is
 * created, so no other object can ever own it.  That makes 0 usable as the
 * "not allocated yet" marker inside an inode's block lists. */
#define NO_BLOCK 0

/* how many block numbers fit in one indirect block */
#define INDIRECT_ENTRY_NUM (BLOCK_SIZE / sizeof(uint32_t))
/* how deep fs_resolve_file() is willing to follow symbolic links */
#define SYMLINK_MAX 8
/* longest path a file system call accepts */
#define PATH_MAX 120

/* * * * * * * * * * * * * * * names and entries * * * * * * * * * * * * * * */

/* directory entry names are padded with zeroes, but a name that uses all 29
 * bytes has no terminator, hence the explicit length limit here */
void fs_copy_name(char* dst, const volatile uint8_t* src)
{
    int i;
    for(i = 0; i < NAME_LEN - 1 && src[i] != '\0'; i++){
        dst[i] = (char)src[i];
    }
    dst[i] = '\0';
}

static void set_name(volatile uint8_t* dst, const char* src)
{
    int i = 0;
    while(i < NAME_LEN - 1 && src[i] != '\0'){
        dst[i] = (uint8_t)src[i];
        i++;
    }
    while(i < NAME_LEN){
        dst[i++] = '\0';
    }
}

static int name_eq(const volatile uint8_t* a, const char* b)
{
    for(int i = 0; i < NAME_LEN - 1; i++){
        if(a[i] != (uint8_t)b[i]){
            return 0;
        }
        if(a[i] == '\0'){
            return 1;
        }
    }
    return b[NAME_LEN - 1] == '\0';
}

/* * * * * * * * * * * * * * * * directories * * * * * * * * * * * * * * * * */

/* A directory occupies exactly one block, addressed by direct_blocks[0] of
 * its inode.  Returns 0 when the inode is not a directory. */
static int dir_block_of(uint16_t inode_id, uint32_t* blk)
{
    volatile inode_t* ino = (volatile inode_t*)read_inode(inode_id);
    if(ino->mode != DIR){
        return 0;
    }
    *blk = ino->direct_blocks[0];
    return 1;
}

/* Look `name` up in the directory stored in `blk`.  On return BLOCK_CACHE
 * always holds `blk`, so the caller can go on working on the entry array. */
static int dir_find(uint32_t blk, const char* name)
{
    read_block(blk);
    volatile dir_t* dir = (volatile dir_t*)BLOCK_CACHE;
    for(int i = 0; i < DIR_ENTRY_NUM; i++){
        if(dir->entry[i].type == EMPTY){
            continue;
        }
        if(name_eq(dir->entry[i].name, name)){
            return i;
        }
    }
    return -1;
}

/* index of the first unused slot of the directory currently in BLOCK_CACHE */
static int dir_free_slot(void)
{
    volatile dir_t* dir = (volatile dir_t*)BLOCK_CACHE;
    for(int i = 0; i < DIR_ENTRY_NUM; i++){
        if(dir->entry[i].type == EMPTY){
            return i;
        }
    }
    return -1;
}

/* Descend into the sub-directory `name`; fails when it does not exist or is
 * not a directory.  "." and ".." are ordinary entries so they just work. */
static int dir_step(uint16_t* inode, uint32_t* blk, const char* name)
{
    int idx = dir_find(*blk, name);
    if(idx < 0){
        return 0;
    }
    volatile dir_t* dir = (volatile dir_t*)BLOCK_CACHE;
    if(dir->entry[idx].type != DIR){
        return 0;
    }
    uint16_t next_inode = dir->entry[idx].inode;

    uint32_t next_blk;
    if(!dir_block_of(next_inode, &next_blk)){
        return 0;
    }
    *inode = next_inode;
    *blk = next_blk;
    return 1;
}

/*
 * Walk `path`, which is absolute when it starts with '/' and relative to the
 * working directory otherwise.  With keep_last == 0 the whole path has to name
 * a directory, which is handed back in *inode / *blk.  With keep_last == 1 the
 * walk stops one component early: *inode / *blk then describe the directory
 * that should contain `last`, which is where every create and remove starts.
 */
static int walk_path(const char* path, int keep_last,
                     uint16_t* inode, uint32_t* blk, char* last)
{
    uint16_t cur_inode;
    uint32_t cur_blk;

    if(path[0] == '/'){
        read_superblock();
        cur_inode = (uint16_t)superblock->root_inode_id;
        if(!dir_block_of(cur_inode, &cur_blk)){
            return 0;
        }
        while(*path == '/'){
            path++;
        }
    }
    else{
        cur_inode = current_dir_inode;
        cur_blk = current_dir_block;
    }

    char comp[NAME_LEN];
    while(*path != '\0'){
        int n = 0;
        while(path[n] != '\0' && path[n] != '/'){
            n++;
        }
        if(n > NAME_LEN - 1){
            return 0;
        }
        for(int i = 0; i < n; i++){
            comp[i] = path[i];
        }
        comp[n] = '\0';
        path += n;
        while(*path == '/'){
            path++;
        }

        if(keep_last && *path == '\0'){
            /* the trailing component is the caller's business */
            if(last != NULL){
                strcpy(last, comp);
            }
            *inode = cur_inode;
            *blk = cur_blk;
            return 1;
        }
        if(!dir_step(&cur_inode, &cur_blk, comp)){
            return 0;
        }
    }

    if(keep_last){
        /* "", "/" and friends have no trailing component to work on */
        return 0;
    }
    *inode = cur_inode;
    *blk = cur_blk;
    return 1;
}

/* * * * * * * * * * * * * * * * * inodes * * * * * * * * * * * * * * * * * * */

/* Map the logical block `idx` of a file onto a physical block, growing the
 * file when `create` is set.  `ino` points into INODE_CACHE and *dirty is set
 * when the inode itself had to change; the caller writes it back.  Returns
 * NO_BLOCK when the block does not exist (or cannot be allocated). */
uint32_t fs_file_block(volatile inode_t* ino, uint32_t idx, int create, int* dirty)
{
    uint32_t blk;

    if(idx < 10){
        blk = ino->direct_blocks[idx];
        if(blk == NO_BLOCK && create){
            blk = alloc_block();
            if(blk == INVALID_BLOCK){
                return NO_BLOCK;
            }
            ino->direct_blocks[idx] = blk;
            *dirty = 1;
            memset((void*)BLOCK_CACHE, 0, BLOCK_SIZE);
            write_block(blk);
        }
        return blk;
    }

    uint32_t which = (idx - 10) / INDIRECT_ENTRY_NUM;
    uint32_t off = (idx - 10) % INDIRECT_ENTRY_NUM;
    if(which >= 2){
        /* beyond 10 + 2 * 1024 blocks the file cannot grow any further */
        return NO_BLOCK;
    }

    uint32_t indirect = ino->indirect_blocks[which];
    if(indirect == NO_BLOCK){
        if(!create){
            return NO_BLOCK;
        }
        indirect = alloc_block();
        if(indirect == INVALID_BLOCK){
            return NO_BLOCK;
        }
        ino->indirect_blocks[which] = indirect;
        *dirty = 1;
        memset((void*)BLOCK_CACHE, 0, BLOCK_SIZE);
        write_block(indirect);
    }

    read_block(indirect);
    volatile uint32_t* table = (volatile uint32_t*)BLOCK_CACHE;
    blk = table[off];
    if(blk == NO_BLOCK && create){
        blk = alloc_block();
        if(blk == INVALID_BLOCK){
            return NO_BLOCK;
        }
        /* allocating only touches the bitmaps, the indirect block is still
         * the one sitting in BLOCK_CACHE */
        table[off] = blk;
        write_block(indirect);
        memset((void*)BLOCK_CACHE, 0, BLOCK_SIZE);
        write_block(blk);
    }
    return blk;
}

/* give every block of a file back; `ino` points into INODE_CACHE */
static void free_file_blocks(volatile inode_t* ino)
{
    for(int i = 0; i < 10; i++){
        if(ino->direct_blocks[i] != NO_BLOCK){
            free_block(ino->direct_blocks[i]);
            ino->direct_blocks[i] = NO_BLOCK;
        }
    }

    for(int k = 0; k < 2; k++){
        uint32_t indirect = ino->indirect_blocks[k];
        if(indirect == NO_BLOCK){
            continue;
        }
        read_block(indirect);
        volatile uint32_t* table = (volatile uint32_t*)BLOCK_CACHE;
        for(uint32_t i = 0; i < INDIRECT_ENTRY_NUM; i++){
            /* free_block works on the bitmaps only, so the table stays put */
            if(table[i] != NO_BLOCK){
                free_block(table[i]);
            }
        }
        free_block(indirect);
        ino->indirect_blocks[k] = NO_BLOCK;
    }
}

/* Drop one reference to a file inode: the data only goes away together with
 * the last hard link pointing at it. */
void fs_drop_ref(uint16_t inode_id)
{
    volatile inode_t* ino = (volatile inode_t*)read_inode(inode_id);
    if(ino->link > 1){
        ino->link = ino->link - 1;
        write_inode(inode_id);
        return;
    }

    free_file_blocks(ino);
    ino->mode = EMPTY;
    ino->size = 0;
    ino->link = 0;
    write_inode(inode_id);
    free_inode(inode_id);
}

/* Fill in a freshly allocated inode without disturbing the seven others that
 * share its sector. */
static void init_inode(uint16_t inode_id, uint32_t mode, uint32_t first_block,
                       uint32_t size, uint32_t link)
{
    volatile inode_t* ino = (volatile inode_t*)read_inode(inode_id);
    memset((void*)ino, 0, sizeof(inode_t));
    ino->mode = mode;
    ino->owner = 0;
    ino->size = size;
    ino->direct_blocks[0] = first_block;
    ino->link = link;
    write_inode(inode_id);
}

/* * * * * * * * * * * * * * * * * lookup * * * * * * * * * * * * * * * * * * */

/* Resolve `path` to whatever it names, without following symbolic links. */
int fs_lookup(const char* path, uint16_t* inode_id, uint8_t* type)
{
    uint16_t parent_inode;
    uint32_t parent_blk;
    char name[NAME_LEN];

    if(!walk_path(path, 1, &parent_inode, &parent_blk, name)){
        return 0;
    }
    int idx = dir_find(parent_blk, name);
    if(idx < 0){
        return 0;
    }

    volatile dir_t* dir = (volatile dir_t*)BLOCK_CACHE;
    *inode_id = dir->entry[idx].inode;
    if(type != NULL){
        *type = dir->entry[idx].type;
    }
    return 1;
}

/* Resolve `path` to a regular file, walking through symbolic links. */
int fs_resolve_file(const char* path, uint16_t* inode_id)
{
    char buffer[PATH_MAX + 1];
    const char* p = path;

    for(int hop = 0; hop < SYMLINK_MAX; hop++){
        uint16_t id;
        uint8_t type;
        if(!fs_lookup(p, &id, &type)){
            return 0;
        }
        if(type == FILE){
            *inode_id = id;
            return 1;
        }
        if(type != SOFTLINK){
            return 0;
        }

        volatile inode_t* ino = (volatile inode_t*)read_inode(id);
        uint32_t blk = ino->direct_blocks[0];
        uint32_t len = ino->size;
        if(blk == NO_BLOCK || len == 0 || len > PATH_MAX){
            return 0;
        }
        read_block(blk);
        for(uint32_t i = 0; i < len; i++){
            buffer[i] = ((volatile char*)BLOCK_CACHE)[i];
        }
        buffer[len] = '\0';
        p = buffer;
    }

    /* too many hops, most likely a loop of symbolic links */
    return 0;
}

/* Create `path` as an empty object of `type` and link it into its parent
 * directory.  Regular files and symbolic links start out without any data
 * block; a directory gets one straight away for its "." and "..". */
int fs_create(const char* path, uint8_t type, uint16_t* inode_id)
{
    uint16_t parent_inode;
    uint32_t parent_blk;
    char name[NAME_LEN];

    if(!walk_path(path, 1, &parent_inode, &parent_blk, name)){
        return 0;
    }
    if(name[0] == '\0' || !strcmp(name, ".") || !strcmp(name, "..")){
        return 0;
    }
    if(dir_find(parent_blk, name) >= 0){
        return 0;
    }
    if(dir_free_slot() < 0){
        return 0;
    }

    uint16_t new_inode = alloc_inode();
    if(new_inode == INVALID_INODE){
        return 0;
    }

    uint32_t new_blk = NO_BLOCK;
    if(type == DIR){
        new_blk = alloc_block();
        if(new_blk == INVALID_BLOCK){
            free_inode(new_inode);
            return 0;
        }

        memset((void*)BLOCK_CACHE, 0, BLOCK_SIZE);
        volatile dir_t* dir = (volatile dir_t*)BLOCK_CACHE;
        dir->entry[0].type = DIR;
        set_name(dir->entry[0].name, ".");
        dir->entry[0].inode = new_inode;
        dir->entry[1].type = DIR;
        set_name(dir->entry[1].name, "..");
        dir->entry[1].inode = parent_inode;
        write_block(new_blk);
    }

    init_inode(new_inode, type, new_blk,
               (type == DIR) ? BLOCK_SIZE : 0,
               (type == DIR) ? 2 : 1);

    /* the slot is looked up again because the caches moved in between */
    read_block(parent_blk);
    int slot = dir_free_slot();
    volatile dir_t* parent = (volatile dir_t*)BLOCK_CACHE;
    parent->entry[slot].type = type;
    set_name(parent->entry[slot].name, name);
    parent->entry[slot].inode = new_inode;
    write_block(parent_blk);

    if(type == DIR){
        /* the new ".." is a fresh reference to the parent */
        volatile inode_t* pino = (volatile inode_t*)read_inode(parent_inode);
        pino->link = pino->link + 1;
        write_inode(parent_inode);
    }

    if(inode_id != NULL){
        *inode_id = new_inode;
    }
    return 1;
}

/* * * * * * * * * * * * * * * * * * mkfs * * * * * * * * * * * * * * * * * * */

int mkfs(int print)
{
    read_superblock();
    if(superblock->magic == MAGIC){
        /* the disk already holds a file system, just adopt its root */
        current_dir_inode = (uint16_t)superblock->root_inode_id;
        current_dir_block = (uint32_t)superblock->root_block_id;
        return 0;
    }

    if(print){
        prints("[FS] Start initializing filesystem!\n");
        prints("[FS] Setting superblock...\n");
    }

    memset((void*)SUPERBLOCK_CACHE, 0, 512);
    superblock->magic = MAGIC;
    superblock->superblock_id = SUPERBLOCK_ID;
    superblock->superblock_num = 1;
    superblock->blockmap_id = BLOCKMAP_BEGIN_ID;
    superblock->blockmap_num = 64;
    superblock->inodemap_id = INODEMAP_ID;
    superblock->inodemap_num = 1;
    superblock->inode_id = INODE_BEGIN_ID;
    superblock->inode_num = INODE_TOTAL;
    superblock->block_id = BLOCK_BEGIN_ID;
    superblock->block_num = BLOCK_TOTAL;
    superblock->root_inode_id = 0;
    superblock->root_block_id = 0;
    superblock->used_inode_num = 0;
    superblock->used_block_num = 0;
    write_superblock();

    if(print){
        prints("     magic : 0x%lx\n", (uint64_t)MAGIC);
        prints("     num sector : %ld, start sector : %ld\n",
               (uint64_t)(BLOCK_BEGIN_ID + (uint64_t)BLOCK_TOTAL * 8 - SUPERBLOCK_ID),
               (uint64_t)SUPERBLOCK_ID);
        prints("     inode map offset : %ld, occupied sector : %ld\n",
               (uint64_t)INODEMAP_ID, (uint64_t)1);
        prints("     block map offset : %ld, occupied sector : %ld\n",
               (uint64_t)BLOCKMAP_BEGIN_ID, (uint64_t)64);
        prints("     inode offset : %ld, occupied sector : %ld\n",
               (uint64_t)INODE_BEGIN_ID, (uint64_t)512);
        prints("     data offset : %ld, occupied sector : %ld\n",
               (uint64_t)BLOCK_BEGIN_ID, (uint64_t)BLOCK_TOTAL * 8);
        prints("     inode entry size : %dB, dir entry size : %dB\n",
               (int)sizeof(inode_t), (int)sizeof(dir_entry_t));
        prints("[FS] Setting inode-map...\n");
        prints("[FS] Setting block-map...\n");
    }

    /* nothing is in use yet */
    memset((void*)INODEMAP_CACHE, 0, 512);
    write_inodemap();
    memset((void*)BLOCKMAP_CACHE, 0, 64 * 512);
    write_blockmap();

    /* the root directory takes inode 0 and block 0 */
    uint16_t root_inode = alloc_inode();
    uint32_t root_block = alloc_block();

    memset((void*)BLOCK_CACHE, 0, BLOCK_SIZE);
    volatile dir_t* dir = (volatile dir_t*)BLOCK_CACHE;
    dir->entry[0].type = DIR;
    set_name(dir->entry[0].name, ".");
    dir->entry[0].inode = root_inode;
    dir->entry[1].type = DIR;
    set_name(dir->entry[1].name, "..");
    dir->entry[1].inode = root_inode;
    write_block(root_block);

    /* the inode sector is built from scratch, there is no sibling to keep */
    memset((void*)INODE_CACHE, 0, 512);
    volatile inode_t* ino = (volatile inode_t*)INODE_CACHE;
    ino->mode = DIR;
    ino->owner = 0;
    ino->size = BLOCK_SIZE;
    ino->direct_blocks[0] = root_block;
    ino->link = 2;
    write_inode(root_inode);

    read_superblock();
    superblock->root_inode_id = root_inode;
    superblock->root_block_id = root_block;
    write_superblock();

    current_dir_inode = root_inode;
    current_dir_block = root_block;

    if(print){
        prints("[FS] Initialize filesystem finished!\n");
    }
    return 1;
}

int do_mkfs(int mode, int* print_location_y)
{
    read_superblock();
    if(mode == 1){
        superblock->magic = 0x0;
        write_superblock();
    }

    if(superblock->magic == MAGIC){
        return 0;
    }

    mkfs(1);
    enable_sum();
    *print_location_y = *print_location_y + 11;
    disable_sum();
    return 1;
}

void do_statfs(int* print_location_y)
{
    read_superblock();
    prints("used inode: %d/%d\n", superblock->used_inode_num, superblock->inode_num);
    prints("used block: %d/%d\n", superblock->used_block_num, superblock->block_num);
    enable_sum();
    *print_location_y = *print_location_y + 2;
    disable_sum();
}

/* * * * * * * * * * * * * * directory operations * * * * * * * * * * * * * * */

/* Copy a path out of user space so that SUM can be turned off again straight
 * away: prints() toggles SUM behind our back, so no user pointer may stay
 * alive into the body of a file system call. */
static void copy_path_in(char* dst, const char* user_path)
{
    enable_sum();
    int i = 0;
    while(i < PATH_MAX && user_path[i] != '\0'){
        dst[i] = user_path[i];
        i++;
    }
    dst[i] = '\0';
    disable_sum();
}

int do_mkdir(char* dirname)
{
    char path[PATH_MAX + 1];
    copy_path_in(path, dirname);
    return fs_create(path, DIR, NULL);
}

/* Remove everything below the directory that lives in `blk`.  Every step
 * re-reads the directory because the recursion keeps reusing BLOCK_CACHE. */
static void remove_tree(uint32_t blk)
{
    for(int i = 0; i < DIR_ENTRY_NUM; i++){
        read_block(blk);
        volatile dir_t* dir = (volatile dir_t*)BLOCK_CACHE;
        uint8_t type = dir->entry[i].type;
        if(type == EMPTY){
            continue;
        }

        char name[NAME_LEN];
        fs_copy_name(name, dir->entry[i].name);
        uint16_t child = dir->entry[i].inode;
        if(!strcmp(name, ".") || !strcmp(name, "..")){
            continue;
        }

        if(type == DIR){
            uint32_t child_blk;
            if(dir_block_of(child, &child_blk)){
                remove_tree(child_blk);
                free_block(child_blk);
            }
            free_inode(child);
        }
        else{
            /* files and symbolic links are reference counted */
            fs_drop_ref(child);
        }

        read_block(blk);
        dir = (volatile dir_t*)BLOCK_CACHE;
        dir->entry[i].type = EMPTY;
        dir->entry[i].inode = 0;
        dir->entry[i].name[0] = '\0';
        write_block(blk);
    }
}

int do_rmdir(char* dirname)
{
    char path[PATH_MAX + 1];
    copy_path_in(path, dirname);

    uint16_t parent_inode;
    uint32_t parent_blk;
    char name[NAME_LEN];
    if(!walk_path(path, 1, &parent_inode, &parent_blk, name)){
        return 0;
    }
    if(name[0] == '\0' || !strcmp(name, ".") || !strcmp(name, "..")){
        return 0;
    }

    int idx = dir_find(parent_blk, name);
    if(idx < 0){
        return 0;
    }
    volatile dir_t* dir = (volatile dir_t*)BLOCK_CACHE;
    if(dir->entry[idx].type != DIR){
        return 0;
    }
    uint16_t target = dir->entry[idx].inode;

    read_superblock();
    if(target == (uint16_t)superblock->root_inode_id){
        return 0;
    }
    /* pulling the ground out from under the shell is never a good idea */
    if(target == current_dir_inode){
        return 0;
    }

    uint32_t target_blk;
    if(!dir_block_of(target, &target_blk)){
        return 0;
    }

    remove_tree(target_blk);
    free_block(target_blk);
    free_inode(target);

    read_block(parent_blk);
    dir = (volatile dir_t*)BLOCK_CACHE;
    dir->entry[idx].type = EMPTY;
    dir->entry[idx].inode = 0;
    dir->entry[idx].name[0] = '\0';
    write_block(parent_blk);

    /* the ".." of the directory we just dropped is gone as well */
    volatile inode_t* pino = (volatile inode_t*)read_inode(parent_inode);
    if(pino->link > 0){
        pino->link = pino->link - 1;
        write_inode(parent_inode);
    }

    return 1;
}

static const char* type_name(uint8_t type)
{
    switch(type){
        case DIR:      return "dir ";
        case FILE:     return "file";
        case SOFTLINK: return "link";
        default:       return "?   ";
    }
}

int do_ls(char* dirname, int mode, int* print_location_y)
{
    char path[PATH_MAX + 1];
    copy_path_in(path, dirname);

    uint16_t dir_inode;
    uint32_t dir_blk;
    if(!walk_path(path, 0, &dir_inode, &dir_blk, NULL)){
        return 0;
    }

    int lines = 0;
    if(mode){
        prints("type  inode  size(B)  link  name\n");
        lines++;
    }

    for(int i = 0; i < DIR_ENTRY_NUM; i++){
        /* prints() only writes to the screen, but read_inode() below does
         * touch the disk caches, so the directory is re-read every round */
        read_block(dir_blk);
        volatile dir_t* dir = (volatile dir_t*)BLOCK_CACHE;
        if(dir->entry[i].type == EMPTY){
            continue;
        }

        char name[NAME_LEN];
        fs_copy_name(name, dir->entry[i].name);
        uint8_t type = dir->entry[i].type;
        uint16_t inode_id = dir->entry[i].inode;

        if(mode){
            volatile inode_t* ino = (volatile inode_t*)read_inode(inode_id);
            prints("%s  %d      %d        %d     %s\n",
                   type_name(type), inode_id, ino->size, ino->link, name);
            lines++;
        }
        else{
            prints("%s  ", name);
        }
    }

    if(!mode){
        prints("\n");
        lines++;
    }

    enable_sum();
    *print_location_y = *print_location_y + lines;
    disable_sum();
    return 1;
}

int do_cd(char* dirname)
{
    char path[PATH_MAX + 1];
    copy_path_in(path, dirname);

    uint16_t dir_inode;
    uint32_t dir_blk;
    if(!walk_path(path, 0, &dir_inode, &dir_blk, NULL)){
        return 0;
    }

    current_dir_inode = dir_inode;
    current_dir_block = dir_blk;
    return 1;
}

/* * * * * * * * * * * * * * * * * * links * * * * * * * * * * * * * * * * * */

int do_link(char* filename, char* newfile, int mode)
{
    char target[PATH_MAX + 1];
    char link[PATH_MAX + 1];
    copy_path_in(target, filename);
    copy_path_in(link, newfile);

    if(target[0] == '\0' || link[0] == '\0'){
        return 0;
    }

    if(mode == 0){
        /* hard link: a second name for an inode that has to exist already */
        uint16_t inode_id;
        uint8_t type;
        if(!fs_lookup(target, &inode_id, &type)){
            return 0;
        }
        if(type != FILE && type != SOFTLINK){
            /* hard links to directories would make the tree cyclic */
            return 0;
        }

        uint16_t parent_inode;
        uint32_t parent_blk;
        char name[NAME_LEN];
        if(!walk_path(link, 1, &parent_inode, &parent_blk, name)){
            return 0;
        }
        if(name[0] == '\0' || !strcmp(name, ".") || !strcmp(name, "..")){
            return 0;
        }
        if(dir_find(parent_blk, name) >= 0){
            return 0;
        }
        int slot = dir_free_slot();
        if(slot < 0){
            return 0;
        }

        volatile dir_t* dir = (volatile dir_t*)BLOCK_CACHE;
        dir->entry[slot].type = type;
        set_name(dir->entry[slot].name, name);
        dir->entry[slot].inode = inode_id;
        write_block(parent_blk);

        volatile inode_t* ino = (volatile inode_t*)read_inode(inode_id);
        ino->link = ino->link + 1;
        write_inode(inode_id);
        return 1;
    }

    /* symbolic link: a small file holding the path of the target, which does
     * not have to exist yet */
    uint16_t inode_id;
    if(!fs_create(link, SOFTLINK, &inode_id)){
        return 0;
    }

    uint32_t blk = alloc_block();
    if(blk == INVALID_BLOCK){
        fs_drop_ref(inode_id);
        return 0;
    }

    int len = strlen(target);
    memset((void*)BLOCK_CACHE, 0, BLOCK_SIZE);
    for(int i = 0; i < len; i++){
        ((volatile char*)BLOCK_CACHE)[i] = target[i];
    }
    write_block(blk);

    volatile inode_t* ino = (volatile inode_t*)read_inode(inode_id);
    ino->direct_blocks[0] = blk;
    ino->size = (uint32_t)len;
    write_inode(inode_id);
    return 1;
}

