/* Walk from the working directory up to the root through the ".." entries:
 * removing a directory the shell is standing in (or below) would leave
 * current_dir_inode pointing at a freed inode. */
static int is_cwd_or_ancestor(uint16_t target)
{
    uint16_t cur = current_dir_inode;

    for(int depth = 0; depth < DIR_ENTRY_NUM; depth++){
        if(cur == target){
            return 1;
        }
        uint32_t blk;
        if(!dir_block_of(cur, &blk)){
            return 0;
        }
        int idx = dir_find(blk, "..");
        if(idx < 0){
            return 0;
        }
        volatile dir_t* dir = (volatile dir_t*)BLOCK_CACHE;
        uint16_t parent = dir->entry[idx].inode;
        if(parent == cur){
            /* the root is its own parent, the walk is over */
            return 0;
        }
        cur = parent;
    }
    return 0;
}

