#include <os/fs.h>
#include <os/disk.h>
#include <os/file.h>
#include <os/sched.h>
#include <os/irq.h>
#include <os/mm.h>
#include <os/string.h>
#include <assert.h>

fd_t fd_list[10];

#define FD_NUM 10
/* longest path a file system call accepts */
#define PATH_MAX 120
/* the shell hands cat a buffer of (SHELL_END - SHELL_BEGIN - 1) * 80 + 1 */
#define CAT_MAX 1120

int do_touch(char* filename)
{
    char path[PATH_MAX + 1];
    fs_copy_path_in(path, filename);

    return fs_create(path, FILE, NULL);
}

int do_cat(char* filename, char* buffer)
{
    char path[PATH_MAX + 1];
    fs_copy_path_in(path, filename);

    /* the shell prints until the first NUL, so an unreadable file has to
     * come back as an empty string rather than as leftover stack junk */
    enable_sum();
    buffer[0] = '\0';
    disable_sum();

    uint16_t inode_id;
    if(!fs_resolve_file(path, &inode_id)){
        return 0;
    }

    volatile inode_t* ino = (volatile inode_t*)read_inode(inode_id);
    uint32_t size = ino->size;
    if(size > CAT_MAX){
        size = CAT_MAX;
    }

    uint32_t done = 0;
    while(done < size){
        uint32_t idx = done / BLOCK_SIZE;
        uint32_t off = done % BLOCK_SIZE;
        uint32_t n = BLOCK_SIZE - off;
        if(n > size - done){
            n = size - done;
        }

        int dirty = 0;
        ino = (volatile inode_t*)read_inode(inode_id);
        uint32_t blk = fs_file_block(ino, idx, 0, &dirty);

        if(blk != 0){
            read_block(blk);
            volatile char* cache = (volatile char*)BLOCK_CACHE;
            enable_sum();
            for(uint32_t i = 0; i < n; i++){
                buffer[done + i] = cache[off + i];
            }
            disable_sum();
        }
        else{
            /* a hole in the middle of the file reads back as zeroes */
            enable_sum();
            for(uint32_t i = 0; i < n; i++){
                buffer[done + i] = 0;
            }
            disable_sum();
        }
        done += n;
    }

    enable_sum();
    buffer[size] = '\0';
    disable_sum();
    return (int)size;
}

int do_fopen(char* filename, int access)
{
    char path[PATH_MAX + 1];
    fs_copy_path_in(path, filename);

    if(access != O_RDONLY && access != O_WRONLY && access != O_RDWR){
        return -1;
    }

    uint16_t inode_id;
    if(!fs_resolve_file(path, &inode_id)){
        /* opening something that is not there yet creates it */
        if(!fs_create(path, FILE, &inode_id)){
            return -1;
        }
    }

    for(int i = 0; i < FD_NUM; i++){
        if(fd_list[i].access == O_EMPTY){
            fd_list[i].inode = inode_id;
