/*
 * Host-side functional test for the Project 6 file system.
 *
 * kernel/fs/{fs,disk,file}.c are compiled natively and driven directly.  The
 * SD card is an array, and the file system's cache pages are mmap'ed at the
 * very physical addresses the kernel uses, so disk.c's kva2pa()/sbi_sd_*()
 * arithmetic is exercised for real rather than stubbed out.
 *
 * The only thing the harness fakes is the boundary the kernel itself fakes on
 * a board: user memory (SUM) and the screen.
 */
#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdarg.h>
#include <sys/mman.h>

#include <type.h>
#include <os/fs.h>
#include <os/disk.h>
#include <os/file.h>

/* ---------------------------------------------------------------- harness */

static int failures;
static int checks;

#define CHECK(cond, ...)                                          \
    do {                                                          \
        checks++;                                                 \
        if (!(cond)) {                                            \
            failures++;                                           \
            printf("  FAIL %s:%d: ", __FILE__, __LINE__);         \
            printf(__VA_ARGS__);                                  \
            printf("\n");                                         \
        }                                                         \
    } while (0)

/* -------------------------------------------------------------- fake disk */

/*
 * The real card is 1GB+.  Only the sectors the tests actually touch are
 * backed, in 64KB chunks, so the simulation stays small.
 */
#define SD_SECTOR_SIZE 512
#define CHUNK_SECTORS  128                 /* 64KB per chunk */
#define SD_SECTORS     (BLOCK_BEGIN_ID + 8 * 4096)
#define CHUNK_COUNT    ((SD_SECTORS / CHUNK_SECTORS) + 2)

static unsigned char *sd_chunk[CHUNK_COUNT];
static long sd_reads, sd_writes;

static unsigned char *sd_sector(unsigned int id)
{
    unsigned int c = id / CHUNK_SECTORS;
    if (c >= CHUNK_COUNT) {
        fprintf(stderr, "sector %u past the end of the simulated card\n", id);
        abort();
    }
    if (sd_chunk[c] == NULL) {
        sd_chunk[c] = calloc(CHUNK_SECTORS, SD_SECTOR_SIZE);
        /* a freshly formatted card is not zeroed; make sure the file system
         * never relies on that by filling it with noise */
        memset(sd_chunk[c], 0xa5, (size_t)CHUNK_SECTORS * SD_SECTOR_SIZE);
    }
    return sd_chunk[c] + (size_t)(id % CHUNK_SECTORS) * SD_SECTOR_SIZE;
}

uintptr_t sbi_sd_read(unsigned int mem_address, unsigned int num_of_blocks,
                      unsigned int block_id)
{
    sd_reads++;
    for (unsigned int i = 0; i < num_of_blocks; i++) {
        memcpy((void *)(uintptr_t)(mem_address + i * SD_SECTOR_SIZE),
               sd_sector(block_id + i), SD_SECTOR_SIZE);
    }
    return 0;
}

uintptr_t sbi_sd_write(unsigned int mem_address, unsigned int num_of_blocks,
                       unsigned int block_id)
{
    sd_writes++;
    for (unsigned int i = 0; i < num_of_blocks; i++) {
        memcpy(sd_sector(block_id + i),
               (void *)(uintptr_t)(mem_address + i * SD_SECTOR_SIZE),
               SD_SECTOR_SIZE);
    }
    return 0;
}

/* ------------------------------------------------------- kernel externals */

void enable_sum(void) {}
void disable_sum(void) {}

static char screen[1 << 16];
static int screen_len;
static int screen_lines;

int prints(const char *fmt, ...)
{
    char buf[512];
    va_list va;
    va_start(va, fmt);
    int n = vsnprintf(buf, sizeof(buf), fmt, va);
    va_end(va);

    for (int i = 0; buf[i]; i++) {
        if (buf[i] == '\n') {
            screen_lines++;
        }
        if (screen_len < (int)sizeof(screen) - 1) {
            screen[screen_len++] = buf[i];
        }
    }
    screen[screen_len] = '\0';
    return n;
}

int printk(const char *fmt, ...) { (void)fmt; return 0; }

static void screen_reset(void)
{
    screen_len = 0;
    screen_lines = 0;
    screen[0] = '\0';
}

/* libs/string.c is not linked in: these four are all the file system uses */
void memset(void *dest, uint8_t val, uint32_t len)
{
    unsigned char *d = dest;
    while (len-- > 0) *d++ = val;
}

int strlen(const char *src)
{
    int n = 0;
    while (src[n]) n++;
    return n;
}

int strcmp(const char *a, const char *b)
{
    while (*a && *a == *b) { a++; b++; }
    return *(const unsigned char *)a - *(const unsigned char *)b;
}

char *strcpy(char *dest, const char *src)
{
    char *r = dest;
    while ((*dest++ = *src++) != '\0') ;
    return r;
}

/* ------------------------------------------------------------- test cases */

static void map_fs_cache(void)
{
    uintptr_t base = SUPERBLOCK_CACHE & ~0xfffUL;
    size_t len = ((FS_CACHE_END - base) + 0xfff) & ~0xfffUL;
    void *p = mmap((void *)base, len, PROT_READ | PROT_WRITE,
                   MAP_PRIVATE | MAP_ANONYMOUS | MAP_FIXED, -1, 0);
    if (p == MAP_FAILED || (uintptr_t)p != base) {
        fprintf(stderr, "cannot map the fs cache at 0x%lx\n", (unsigned long)base);
        exit(2);
    }
}

static void wipe_card(void)
{
    for (int i = 0; i < CHUNK_COUNT; i++) {
        free(sd_chunk[i]);
        sd_chunk[i] = NULL;
    }
    for (int i = 0; i < 10; i++) {
        fd_list[i].access = O_EMPTY;
    }
}

static void test_mkfs(void)
{
    printf("[p6_fs] mkfs\n");
    wipe_card();

    screen_reset();
    CHECK(mkfs(1) == 1, "mkfs on a blank card must report that it built one");
    CHECK(screen_lines == 11,
          "mkfs(1) printed %d lines, do_mkfs() advances the cursor by 11",
          screen_lines);

    read_superblock();
    CHECK(superblock->magic == MAGIC, "magic not written");
    CHECK(superblock->inode_num == INODE_TOTAL, "inode_num = %lu",
          (unsigned long)superblock->inode_num);
    CHECK(superblock->block_num == BLOCK_TOTAL, "block_num = %lu",
          (unsigned long)superblock->block_num);
    CHECK(superblock->used_inode_num == 1, "root inode not accounted for (%lu)",
          (unsigned long)superblock->used_inode_num);
    CHECK(superblock->used_block_num == 1, "root block not accounted for (%lu)",
          (unsigned long)superblock->used_block_num);
    CHECK(current_dir_inode == (uint16_t)superblock->root_inode_id,
          "working directory is not the root");

    /* a second mkfs must recognise the existing file system */
    screen_reset();
    CHECK(mkfs(0) == 0, "mkfs must not reformat a card that already has a fs");
    CHECK(current_dir_inode == (uint16_t)superblock->root_inode_id,
          "mkfs must restore the working directory when it adopts a fs");

    /* the root directory has "." and ".." and nothing else */
    read_block((uint32_t)superblock->root_block_id);
    dir_t *root = (dir_t *)BLOCK_CACHE;
    CHECK(root->entry[0].type == DIR && !strcmp((char *)root->entry[0].name, "."),
          "root is missing '.'");
    CHECK(root->entry[1].type == DIR && !strcmp((char *)root->entry[1].name, ".."),
          "root is missing '..'");
    int used = 0;
    for (int i = 0; i < DIR_ENTRY_NUM; i++) {
        if (root->entry[i].type != EMPTY) used++;
    }
    CHECK(used == 2, "a fresh root has %d entries, expected 2", used);
}

static void test_bitmaps(void)
{
    printf("[p6_fs] inode and block allocation\n");
    wipe_card();
    mkfs(0);

    read_superblock();
    uint64_t inode0 = superblock->used_inode_num;
    uint64_t block0 = superblock->used_block_num;

    uint16_t a = alloc_inode();
    uint16_t b = alloc_inode();
    CHECK(a != INVALID_INODE && b != INVALID_INODE, "inode allocation failed");
    CHECK(a != b, "alloc_inode handed out %u twice", a);
    read_superblock();
    CHECK(superblock->used_inode_num == inode0 + 2,
          "used_inode_num = %lu after two allocations",
          (unsigned long)superblock->used_inode_num);

    uint32_t x = alloc_block();
    uint32_t y = alloc_block();
    CHECK(x != INVALID_BLOCK && y != INVALID_BLOCK, "block allocation failed");
    CHECK(x != y, "alloc_block handed out %u twice", x);
    CHECK(x != 0 && y != 0, "block 0 belongs to the root, it must never be reused");
    read_superblock();
    CHECK(superblock->used_block_num == block0 + 2,
          "used_block_num = %lu after two allocations",
          (unsigned long)superblock->used_block_num);

    /* a freed object comes back on the next allocation */
    free_inode(a);
    free_block(x);
    read_superblock();
    CHECK(superblock->used_inode_num == inode0 + 1, "free_inode did not adjust the count");
    CHECK(superblock->used_block_num == block0 + 1, "free_block did not adjust the count");
    CHECK(alloc_inode() == a, "the freed inode was not reused");
    CHECK(alloc_block() == x, "the freed block was not reused");

    /* freeing twice must not drive the counters below zero */
    read_superblock();
    uint64_t before = superblock->used_block_num;
    free_block(y);
    free_block(y);
    read_superblock();
    CHECK(superblock->used_block_num == before - 1,
          "a double free moved used_block_num from %lu to %lu",
          (unsigned long)before, (unsigned long)superblock->used_block_num);

    /* the bitmaps survive a round trip through the card */
    uint32_t z = alloc_block();
    memset((void *)BLOCKMAP_CACHE, 0, 64 * 512);
    read_blockmap();
    CHECK((((volatile uint8_t *)BLOCKMAP_CACHE)[z / 8] >> (z % 8)) & 1,
          "block %u is not marked used on the card", z);
}

static int y_pos;

static void test_directories(void)
{
    printf("[p6_fs] mkdir / cd / ls / rmdir\n");
    wipe_card();
    mkfs(0);

    CHECK(do_mkdir("dir1") == 1, "mkdir dir1");
    CHECK(do_mkdir("dir2") == 1, "mkdir dir2");
    CHECK(do_mkdir("dir1") == 0, "mkdir must refuse an existing name");

    /* ls of the root lists both, plus "." and ".." */
    screen_reset();
    y_pos = 0;
    CHECK(do_ls("\0", 0, &y_pos) == 1, "ls of the root failed");
    CHECK(strstr(screen, "dir1") && strstr(screen, "dir2"),
          "ls did not list the new directories: %s", screen);
    CHECK(y_pos == screen_lines, "ls reported %d lines but printed %d",
          y_pos, screen_lines);

    /* cd and relative paths */
    CHECK(do_cd("dir1") == 1, "cd dir1");
    CHECK(do_mkdir("inner") == 1, "mkdir inner");
    CHECK(do_cd("inner") == 1, "cd inner");
    CHECK(do_cd("..") == 1, "cd ..");
    CHECK(do_cd("nope") == 0, "cd into a directory that does not exist");

    /* absolute paths */
    CHECK(do_cd("/dir2") == 1, "cd /dir2");
    CHECK(do_mkdir("/dir2/sub") == 1, "mkdir with an absolute path");
    CHECK(do_cd("/dir1/inner") == 1, "cd through two levels");
    CHECK(do_cd("/") == 1, "cd to the root");

    /* ls of another directory by path */
    screen_reset();
    y_pos = 0;
    CHECK(do_ls("dir2", 0, &y_pos) == 1, "ls dir2");
    CHECK(strstr(screen, "sub") != NULL, "ls dir2 did not show sub: %s", screen);
    CHECK(do_ls("dir2/missing", 0, &y_pos) == 0, "ls of a missing path must fail");

    /* the detailed listing has a header plus one line per entry */
    screen_reset();
    y_pos = 0;
    CHECK(do_ls("dir2", 1, &y_pos) == 1, "ls -al dir2");
    CHECK(y_pos == screen_lines, "ls -al reported %d lines but printed %d",
          y_pos, screen_lines);
    CHECK(screen_lines == 4, "ls -al of dir2 printed %d lines, expected 4",
          screen_lines);

    /* ".." really points at the parent */
    CHECK(do_cd("/dir1/inner") == 1, "cd /dir1/inner");
    CHECK(do_cd("../..") == 1, "cd ../..");
    screen_reset();
    y_pos = 0;
    do_ls("\0", 0, &y_pos);
    CHECK(strstr(screen, "dir1") && strstr(screen, "dir2"),
          "'../..' did not land in the root: %s", screen);

    /* rmdir removes the whole subtree */
    read_superblock();
    uint64_t inodes_before = superblock->used_inode_num;
    CHECK(do_rmdir("dir1") == 1, "rmdir dir1");
    CHECK(do_cd("dir1") == 0, "the removed directory is still reachable");
    read_superblock();
    CHECK(superblock->used_inode_num == inodes_before - 2,
          "rmdir freed %ld inodes, dir1 and inner make 2",
          (long)(inodes_before - superblock->used_inode_num));

    /* the working directory (and anything above it) is off limits */
    CHECK(do_cd("/dir2/sub") == 1, "cd /dir2/sub");
    CHECK(do_rmdir("/dir2/sub") == 0, "rmdir of the working directory must fail");
    CHECK(do_rmdir("/dir2") == 0, "rmdir of a parent of the working directory must fail");
    CHECK(do_cd("/") == 1, "cd /");
    CHECK(do_rmdir("/dir2") == 1, "rmdir /dir2 once nothing stands in it");
    CHECK(do_rmdir("/") == 0, "the root cannot be removed");
    CHECK(do_rmdir("nothing") == 0, "rmdir of a missing directory must fail");
}

static void test_files(void)
{
    printf("[p6_fs] touch / cat / fopen / fread / fwrite\n");
    wipe_card();
    mkfs(0);

    char buffer[2048];

    CHECK(do_touch("a.txt") == 1, "touch a.txt");
    CHECK(do_touch("a.txt") == 0, "touch must refuse an existing name");
    CHECK(do_cat("a.txt", buffer) == 0, "a fresh file is empty");
    CHECK(buffer[0] == '\0', "cat of an empty file must produce an empty string");

    buffer[0] = 'x';
    CHECK(do_cat("missing.txt", buffer) == 0, "cat of a missing file");
    CHECK(buffer[0] == '\0', "cat must clear the buffer when it fails");

    /* the same sequence test_fs.c runs on the board */
    int fd = do_fopen("1.txt", O_RDWR);
    CHECK(fd >= 0, "fopen must create a file that is not there yet");
    for (int i = 0; i < 10; i++) {
        CHECK(do_fwrite(fd, "hello world!\n", 13) == 13, "fwrite %d", i);
    }
    for (int i = 0; i < 10; i++) {
        memset(buffer, 0, 32);
        CHECK(do_fread(fd, buffer, 13) == 13, "fread %d", i);
        CHECK(!memcmp(buffer, "hello world!\n", 13),
              "round %d read back '%.13s'", i, buffer);
    }
    CHECK(do_fread(fd, buffer, 13) == 0, "reading past the end must return 0");
    do_fclose(fd);

    /* the file survives being closed and reopened */
    fd = do_fopen("1.txt", O_RDONLY);
    CHECK(fd >= 0, "reopen 1.txt");
    CHECK(do_fread(fd, buffer, 13) == 13, "fread after reopen");
    CHECK(!memcmp(buffer, "hello world!\n", 13), "content changed across reopen");
    CHECK(do_fwrite(fd, "nope", 4) == 0, "a read-only descriptor must reject writes");
    do_fclose(fd);

    /* cat sees the same bytes */
    memset(buffer, 0, sizeof(buffer));
    CHECK(do_cat("1.txt", buffer) == 130, "cat returned the wrong length");
    CHECK(!memcmp(buffer, "hello world!\n", 13), "cat content");
    CHECK(buffer[130] == '\0', "cat must terminate the buffer");

    /* descriptors are recycled */
    int fds[10];
    for (int i = 0; i < 10; i++) {
        fds[i] = do_fopen("1.txt", O_RDWR);
        CHECK(fds[i] >= 0 && fds[i] < 10, "descriptor %d out of range: %d", i, fds[i]);
    }
    CHECK(do_fopen("1.txt", O_RDWR) == -1, "the eleventh open must fail");
    do_fclose(fds[3]);
    CHECK(do_fopen("1.txt", O_RDWR) == 3, "the closed descriptor was not reused");
    for (int i = 0; i < 10; i++) do_fclose(i);

    /* files live in directories, not only in the root */
    CHECK(do_mkdir("sub") == 1, "mkdir sub");
    CHECK(do_touch("sub/b.txt") == 1, "touch through a path");
    CHECK(do_cd("sub") == 1, "cd sub");
    fd = do_fopen("b.txt", O_RDWR);
    CHECK(fd >= 0, "open b.txt from inside sub");
    CHECK(do_fwrite(fd, "inner", 5) == 5, "write b.txt");
    do_fclose(fd);
    CHECK(do_cd("/") == 1, "cd /");
    memset(buffer, 0, sizeof(buffer));
    CHECK(do_cat("/sub/b.txt", buffer) == 5, "cat by absolute path");
    CHECK(!strcmp(buffer, "inner"), "b.txt reads back as '%s'", buffer);
}

static void test_large_file(void)
{
    printf("[p6_fs] a file large enough to need indirect blocks\n");
    wipe_card();
    mkfs(0);

    /* 10 direct blocks are 40KB; go past that so both the indirect block and
     * the block that indexes it are exercised */
    const int total = 96 * 1024;
    char *out = malloc(total);
    char *in = malloc(total);
    for (int i = 0; i < total; i++) {
        out[i] = (char)(i * 7 + (i >> 8));
    }

    int fd = do_fopen("big.bin", O_RDWR);
    CHECK(fd >= 0, "open big.bin");

    /* write in awkward chunks so that block boundaries fall inside a call */
    int done = 0;
    while (done < total) {
        int n = (total - done > 777) ? 777 : total - done;
        int w = do_fwrite(fd, out + done, n);
        CHECK(w == n, "fwrite at %d returned %d", done, w);
        if (w != n) break;
        done += w;
    }

    memset(in, 0, total);
    done = 0;
    while (done < total) {
        int n = (total - done > 999) ? 999 : total - done;
        int r = do_fread(fd, in + done, n);
        CHECK(r == n, "fread at %d returned %d", done, r);
        if (r != n) break;
        done += r;
    }
    CHECK(!memcmp(out, in, total), "the large file did not read back unchanged");

    do_fclose(fd);

    /* and again through a fresh descriptor, so nothing depended on the cache */
    fd = do_fopen("big.bin", O_RDONLY);
    memset(in, 0, total);
    done = 0;
    while (done < total) {
        int r = do_fread(fd, in + done, 4096);
        if (r <= 0) break;
        done += r;
    }
    CHECK(done == total, "reopened big.bin is %d bytes, expected %d", done, total);
    CHECK(!memcmp(out, in, total), "big.bin changed after reopening");
    do_fclose(fd);

    /* removing it gives every block back */
    read_superblock();
    uint64_t used = superblock->used_block_num;
    CHECK(do_mkdir("tmp") == 1, "mkdir tmp");
    CHECK(do_link("big.bin", "tmp/copy.bin", 0) == 1, "hard link into tmp");
    CHECK(do_rmdir("tmp") == 1, "rmdir tmp");
    read_superblock();
    CHECK(superblock->used_block_num == used,
          "removing a hard link freed %ld blocks, it must free none",
          (long)(used - superblock->used_block_num));

    free(out);
    free(in);
}

static void test_links(void)
{
    printf("[p6_fs] hard and soft links\n");
    wipe_card();
    mkfs(0);

    char buffer[2048];

    int fd = do_fopen("orig.txt", O_RDWR);
    CHECK(fd >= 0, "open orig.txt");
    CHECK(do_fwrite(fd, "shared payload", 14) == 14, "write orig.txt");
    do_fclose(fd);

    /* hard link: same inode, one more reference */
    CHECK(do_link("orig.txt", "hard.txt", 0) == 1, "ln orig.txt hard.txt");
    CHECK(do_link("orig.txt", "hard.txt", 0) == 0, "ln must refuse an existing name");
    CHECK(do_link("missing.txt", "x.txt", 0) == 0, "a hard link needs a target");

    uint16_t a, b;
    uint8_t ta, tb;
    CHECK(fs_lookup("orig.txt", &a, &ta) == 1, "lookup orig.txt");
    CHECK(fs_lookup("hard.txt", &b, &tb) == 1, "lookup hard.txt");
    CHECK(a == b, "a hard link must share the inode (%u vs %u)", a, b);

    volatile inode_t *ino = (volatile inode_t *)read_inode(a);
    CHECK(ino->link == 2, "link count is %u, expected 2", ino->link);

    memset(buffer, 0, sizeof(buffer));
    CHECK(do_cat("hard.txt", buffer) == 14, "cat through the hard link");
    CHECK(!strcmp(buffer, "shared payload"), "hard link content: %s", buffer);

    /* writing through one name is visible under the other */
    fd = do_fopen("hard.txt", O_RDWR);
    CHECK(fd >= 0, "open hard.txt");
    CHECK(do_fwrite(fd, "HARD", 4) == 4, "write hard.txt");
    do_fclose(fd);
    memset(buffer, 0, sizeof(buffer));
    do_cat("orig.txt", buffer);
    CHECK(!memcmp(buffer, "HARD", 4), "the hard link did not share the data: %s", buffer);

    /* soft link: its own inode, resolved on use */
    CHECK(do_link("orig.txt", "soft.txt", 1) == 1, "ln -s orig.txt soft.txt");
    uint16_t s;
    uint8_t ts;
    CHECK(fs_lookup("soft.txt", &s, &ts) == 1, "lookup soft.txt");
    CHECK(ts == SOFTLINK, "soft.txt has type %u, expected SOFTLINK", ts);
    CHECK(s != a, "a soft link must have its own inode");

    memset(buffer, 0, sizeof(buffer));
    CHECK(do_cat("soft.txt", buffer) == 14, "cat through the soft link");
    CHECK(!memcmp(buffer, "HARD", 4), "soft link content: %s", buffer);

    uint16_t resolved;
    CHECK(fs_resolve_file("soft.txt", &resolved) == 1, "resolve soft.txt");
    CHECK(resolved == a, "the soft link resolved to inode %u, expected %u", resolved, a);

    /* a soft link may point at something that is not there (yet) */
    CHECK(do_link("later.txt", "dangling.txt", 1) == 1, "a dangling soft link is allowed");
    CHECK(do_cat("dangling.txt", buffer) == 0, "a dangling soft link reads as empty");
    CHECK(do_touch("later.txt") == 1, "touch later.txt");
    fd = do_fopen("later.txt", O_RDWR);
    do_fwrite(fd, "now here", 8);
    do_fclose(fd);
    memset(buffer, 0, sizeof(buffer));
    CHECK(do_cat("dangling.txt", buffer) == 8, "the soft link now resolves");
    CHECK(!strcmp(buffer, "now here"), "late target content: %s", buffer);

    /* a loop of soft links must not hang the kernel */
    CHECK(do_link("loop_b", "loop_a", 1) == 1, "ln -s loop_b loop_a");
    CHECK(do_link("loop_a", "loop_b", 1) == 1, "ln -s loop_a loop_b");
    uint16_t dummy;
    CHECK(fs_resolve_file("loop_a", &dummy) == 0, "a symlink loop must be refused");
    CHECK(do_cat("loop_a", buffer) == 0, "cat of a symlink loop must give up");

    /* soft links live in directories too */
    CHECK(do_mkdir("d") == 1, "mkdir d");
    CHECK(do_link("/orig.txt", "d/rel.txt", 1) == 1, "soft link inside a directory");
    memset(buffer, 0, sizeof(buffer));
    CHECK(do_cat("d/rel.txt", buffer) == 14, "cat d/rel.txt");
}

static void test_persistence(void)
{
    printf("[p6_fs] state survives a remount\n");
    wipe_card();
    mkfs(0);

    CHECK(do_mkdir("keep") == 1, "mkdir keep");
    int fd = do_fopen("keep/note.txt", O_RDWR);
    CHECK(fd >= 0, "open keep/note.txt");
    CHECK(do_fwrite(fd, "persisted", 9) == 9, "write note.txt");
    do_fclose(fd);

    /* throw the caches away, as a reboot would */
    memset((void *)SUPERBLOCK_CACHE, 0, FS_CACHE_END - SUPERBLOCK_CACHE);
    current_dir_inode = 0xdead;
    current_dir_block = 0xdeadbeef;

    CHECK(mkfs(0) == 0, "the card still holds a file system");

    char buffer[2048];
    memset(buffer, 0, sizeof(buffer));
    CHECK(do_cat("keep/note.txt", buffer) == 9, "cat after the remount");
    CHECK(!strcmp(buffer, "persisted"), "note.txt reads back as '%s'", buffer);

    /* mkfs -f wipes everything */
    read_superblock();
    superblock->magic = 0;
    write_superblock();
    CHECK(mkfs(0) == 1, "a cleared magic forces a rebuild");
    CHECK(do_cat("keep/note.txt", buffer) == 0, "the old tree must be gone");
    read_superblock();
    CHECK(superblock->used_inode_num == 1, "a rebuilt fs has only the root inode");
    CHECK(superblock->used_block_num == 1, "a rebuilt fs has only the root block");
}

static void test_edge_cases(void)
{
    printf("[p6_fs] awkward inputs\n");
    wipe_card();
    mkfs(0);

    CHECK(do_mkdir("") == 0, "mkdir of an empty name");
    CHECK(do_mkdir("/") == 0, "mkdir of the root");
    CHECK(do_mkdir(".") == 0, "mkdir of '.'");
    CHECK(do_mkdir("..") == 0, "mkdir of '..'");
    CHECK(do_mkdir("a/b") == 0, "mkdir must not invent intermediate directories");

    CHECK(do_cd("") == 1, "cd of an empty path stays put");
    CHECK(do_mkdir("dir") == 1, "mkdir dir");
    CHECK(do_cd("dir/") == 1, "a trailing slash is harmless");
    CHECK(do_cd("//") == 1, "repeated slashes collapse");
    CHECK(do_cd("/dir//") == 1, "repeated slashes in the middle collapse");

    /* a name longer than a directory entry can hold is refused, not truncated */
    char toolong[64];
    memset(toolong, 'x', sizeof(toolong));
    toolong[40] = '\0';
    CHECK(do_mkdir(toolong) == 0, "an over-long name must be refused");

    /* the longest name that does fit round-trips */
    char longest[NAME_LEN];
    memset(longest, 'y', NAME_LEN - 1);
    longest[NAME_LEN - 1] = '\0';
    CHECK(do_mkdir(longest) == 1, "a 28 character name must be accepted");
    CHECK(do_cd(longest) == 1, "cd into the 28 character name");
    CHECK(do_cd("/") == 1, "cd /");

    /* a file is not a directory and the other way round */
    CHECK(do_touch("file") == 1, "touch file");
    CHECK(do_cd("file") == 0, "cd into a regular file must fail");
    CHECK(do_ls("file", 0, &y_pos) == 0, "ls of a regular file must fail");
    CHECK(do_rmdir("file") == 0, "rmdir of a regular file must fail");
    CHECK(do_link("dir", "dirlink", 0) == 0, "a hard link to a directory must fail");

    /* file descriptors are validated */
    char buffer[64];
    CHECK(do_fread(-1, buffer, 8) == 0, "fread on a negative descriptor");
    CHECK(do_fread(99, buffer, 8) == 0, "fread past the descriptor table");
    CHECK(do_fread(0, buffer, 8) == 0, "fread on a descriptor that is not open");
    CHECK(do_fwrite(0, buffer, 8) == 0, "fwrite on a descriptor that is not open");
    do_fclose(-1);
    do_fclose(99);
    CHECK(do_fopen("file", 0) == -1, "fopen must reject an empty access mode");
    CHECK(do_fopen("file", 99) == -1, "fopen must reject an unknown access mode");

    int fd = do_fopen("file", O_RDWR);
    CHECK(fd >= 0, "open file");
    CHECK(do_fwrite(fd, buffer, 0) == 0, "a zero length write does nothing");
    CHECK(do_fread(fd, buffer, 0) == 0, "a zero length read does nothing");
    CHECK(do_fwrite(fd, buffer, -5) == 0, "a negative length is refused");
    do_fclose(fd);

    /* filling a directory up: 128 slots, two of which are "." and ".." */
    CHECK(do_mkdir("full") == 1, "mkdir full");
    CHECK(do_cd("full") == 1, "cd full");
    char name[16];
    int made = 0;
    for (int i = 0; i < 130; i++) {
        snprintf(name, sizeof(name), "f%d", i);
        if (do_touch(name) == 1) made++;
    }
    CHECK(made == DIR_ENTRY_NUM - 2,
          "a directory took %d entries beyond '.' and '..', expected %d",
          made, DIR_ENTRY_NUM - 2);
    CHECK(do_cd("/") == 1, "cd /");
    CHECK(do_rmdir("full") == 1, "rmdir a directory with 126 files in it");
}

int main(void)
{
    map_fs_cache();

    test_mkfs();
    test_bitmaps();
    test_directories();
    test_files();
    test_large_file();
    test_links();
    test_persistence();
    test_edge_cases();

    printf("[p6_fs] %d checks, %d failures (%ld sd reads, %ld sd writes)\n",
           checks, failures, sd_reads, sd_writes);
    return failures ? 1 : 0;
}

