/*
 * Reaching the far end of the second indirect block through fwrite() would
 * mean pushing eight megabytes through the simulated card, so the block map
 * is exercised directly instead: every interesting index around the three
 * boundaries has to get its own block, and looking it up again without
 * `create` has to give the same answer back.
 */
static void test_block_map_boundaries(void)
{
    printf("[p6_fs] direct / indirect block boundaries\n");
    wipe_card();
    mkfs(0);

    const uint32_t last_direct = 9;
    const uint32_t first_ind0 = 10;
    const uint32_t last_ind0 = 10 + 1024 - 1;
    const uint32_t first_ind1 = 10 + 1024;
    const uint32_t last_ind1 = 10 + 2048 - 1;
    const uint32_t past_end = 10 + 2048;

    uint32_t idx[] = { 0, 1, last_direct, first_ind0, first_ind0 + 1,
                       last_ind0 - 1, last_ind0, first_ind1, first_ind1 + 1,
                       last_ind1 };
    const int n = (int)(sizeof(idx) / sizeof(idx[0]));
    uint32_t got[16];

    CHECK(do_touch("map.bin") == 1, "touch map.bin");
    uint16_t id;
    CHECK(fs_lookup("map.bin", &id, NULL) == 1, "lookup map.bin");

    for (int i = 0; i < n; i++) {
        int dirty = 0;
        volatile inode_t *ino = (volatile inode_t *)read_inode(id);
        got[i] = fs_file_block(ino, idx[i], 1, &dirty);
        if (dirty) write_inode(id);
        CHECK(got[i] != 0, "logical block %u could not be allocated", idx[i]);
    }

    /* every logical block has to sit in a physical block of its own */
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
