    ino = (volatile inode_t *)read_inode(hid);
    CHECK(fs_file_block(ino, 5, 0, &dirty) == 0, "an unwritten direct block");
    CHECK(fs_file_block(ino, 500, 0, &dirty) == 0, "an unwritten indirect block");
    CHECK(dirty == 0, "a read-only walk must leave the inode alone");

    /* removing the file gives back the data blocks, the indirect blocks and
     * the inode: nothing may leak */
    read_superblock();
    uint64_t inodes = superblock->used_inode_num;
    uint64_t blocks = superblock->used_block_num;
    fs_drop_ref(id);
    read_superblock();
    CHECK(superblock->used_inode_num == inodes - 1,
          "dropping map.bin freed %ld inodes",
          (long)(inodes - superblock->used_inode_num));
    /* n data blocks plus the two indirect blocks that index them */
    CHECK(superblock->used_block_num == blocks - (uint64_t)n - 2,
          "dropping map.bin freed %ld blocks, expected %d",
          (long)(blocks - superblock->used_block_num), n + 2);
}

