/*
 * Bring every page of the user range [addr, addr + len) into memory before
 * the kernel reads or writes it with SUM set.  A page fault taken in kernel
 * mode would re-enter exception_handler_entry, which acquires the big kernel
 * lock this hart is already holding -- so the fault has to be provoked here,
 * where it is just an ordinary allocation.  Nothing can evict the pages again
 * before the copy: only alloc_user_page() swaps, and the kernel lock keeps
 * the other hart out for the whole system call.
 */
void prepare_user_range(uintptr_t addr, size_t len)
{
    if(len == 0){
        return;
    }
    uintptr_t pgdir = (uintptr_t)current_running[cpu_id]->pgdir;
    uintptr_t end = addr + len;
    for(uintptr_t va = ROUNDDOWN(addr, PAGE_SIZE); va < end; va += PAGE_SIZE){
        alloc_page_helper(va, pgdir);
    }
}

