/*
 * The receive completion interrupt is delivered on whichever hart happens to
 * be running, in whatever address space happens to be installed -- and with
 * SUM cleared, so the handler cannot touch user memory at all.  It therefore
 * drops the frames into this kernel staging area, and do_net_recv() hands
 * them over once the caller has been scheduled again.
 */
static EthernetFrame recv_stage[RXBD_CNT];
static size_t recv_stage_len[RXBD_CNT];

/* the task whose interrupt driven receive is currently in flight */
static pcb_t *recv_waiter;

/*
 * Copy `num_packet` frames out of a kernel buffer into the caller's `addr`,
 * back to back, and record their lengths in `frLength`.  Returns the total
 * number of bytes handed over.
 */
static long deliver_frames(uintptr_t addr, size_t length, int num_packet,
                           size_t *frLength, const uint8_t *src,
                           const size_t *src_len)
{
    size_t total = 0;
    for(int i = 0; i < num_packet; i++){
        total += src_len[i];
    }
    if(total > length){
        /* never write past the buffer the caller gave us */
        total = length;
    }

    /* the pages have to be resident before SUM is turned on: a fault taken
     * here would be a kernel fault, and those deadlock on the kernel lock */
    prepare_user_range(addr, total);
    prepare_user_range((uintptr_t)frLength, sizeof(size_t) * num_packet);

    enable_sum();
    rx_curr = addr;
    rx_tail = 0;
    for(int i = 0; i < num_packet; i++){
        size_t n = src_len[i];
        if(rx_tail + n > total){
            n = total - rx_tail;
        }
        memcpy((uint8_t*)rx_curr, (uint8_t*)src + rx_tail, (uint32_t)n);
        *(frLength + i) = src_len[i];
        rx_curr += n;
        rx_tail += n;
    }
    disable_sum();
    return (long)rx_tail;
}

long do_net_recv(uintptr_t addr, size_t length, int num_packet, size_t* frLength)
{
    // receive packet by calling network driver's function
    // wait until you receive enough packets(`num_packet`).
    if(num_packet <= 0 || num_packet > RXBD_CNT){
        return -1;
    }
    if(net_poll_mode != 0 && net_poll_mode != 1){
        return -1;
    }

    /* interrupts must stay off until we are queued on net_recv_queue,
     * otherwise the handler would wake up an empty queue */
    disable_preempt();

    /*
     * Second half of an interrupt driven receive.  scheduler() is not a
     * context switch in this kernel -- the switch happens in
     * ret_from_exception -- so a blocking system call cannot resume where it
     * left off.  Like do_waitpid(), this one rewinds sepc so that the `ecall`
     * runs again, and the retry lands here with the frames already staged and
     * the caller's own page table installed.
     */
    if(recv_waiter == current_running[cpu_id]){
        recv_waiter = NULL;
        long ret = deliver_frames(addr, length, num_packet, frLength,
                                  (const uint8_t*)recv_stage, recv_stage_len);
        enable_preempt();
        return ret;
    }

    if(net_poll_mode == 1 && recv_waiter != NULL){
        /* somebody else owns the single receive transaction */
        enable_preempt();
        return -1;
    }

    recv_transaction = 1;
    for(int i = 0; i < num_packet; i++){
        memset(&rx_buffers[i], 0, sizeof(EthernetFrame));
        rx_len[i] = 0;
        recv_stage_len[i] = 0;
    }

    if(net_poll_mode == 0){
        /* poll mode: spin until every descriptor has been handed back */
        EmacPsRecv(&EmacPsInstance, 0, num_packet);
        EmacPsWaitRecv(&EmacPsInstance, num_packet, rx_len);

        size_t poll_len[RXBD_CNT];
        for(int i = 0; i < num_packet; i++){
            poll_len[i] = rx_len[i];
        }
        /* rx_buffers holds one whole frame per slot, deliver_frames() wants
         * them back to back, so pack them into the staging area first */
        size_t off = 0;
        for(int i = 0; i < num_packet; i++){
            memcpy((uint8_t*)recv_stage + off, (uint8_t*)&rx_buffers[i], rx_len[i]);
            off += rx_len[i];
        }

        recv_transaction = 0;
        long ret = deliver_frames(addr, length, num_packet, frLength,
                                  (const uint8_t*)recv_stage, poll_len);
        enable_preempt();
        return ret;
    }

    /*
     * Interrupt mode, first half: point the handler at the kernel staging
     * area, arm the descriptors and go to sleep.  XEmacPsRecvHandler() runs
     * with SUM cleared in whatever address space happens to be installed, so
     * it can only ever write into kernel memory.
     */
    _addr = (uintptr_t)recv_stage;
    _num_packet = num_packet;
    _frLength = recv_stage_len;
    EmacPsRecv(&EmacPsInstance, 0, num_packet);

    recv_waiter = current_running[cpu_id];
    /* handle_syscall() already advanced sepc past the `ecall` */
    regs_context_t *regs = (regs_context_t *)current_running[cpu_id]->kernel_sp;
    regs->sepc = regs->sepc - 4;

    do_block(&current_running[cpu_id]->list, &net_recv_queue);
    scheduler();
    enable_preempt();

    /* handle_syscall() writes this into a0, which is the very `addr` the
     * retried `ecall` picks up again */
    return (long)addr;
}

