    if(net_poll_mode == 1 && recv_waiter != NULL){
        /* somebody else owns the single receive transaction */
        enable_preempt();
        return -1;
    }

    recv_transaction = 1;
    for(int i = 0; i < num_packet; i++){
        memset(&rx_buffers[i], 0, sizeof(EthernetFrame));
        rx_len[i] = 0;
        recv_stage_len[i] = 0;
    }

    if(net_poll_mode == 0){
        /* poll mode: spin until every descriptor has been handed back */
        EmacPsRecv(&EmacPsInstance, 0, num_packet);
        EmacPsWaitRecv(&EmacPsInstance, num_packet, rx_len);

        size_t poll_len[RXBD_CNT];
        for(int i = 0; i < num_packet; i++){
            poll_len[i] = rx_len[i];
        }
        /* rx_buffers holds one whole frame per slot, deliver_frames() wants
         * them back to back, so pack them into the staging area first */
        size_t off = 0;
        for(int i = 0; i < num_packet; i++){
            memcpy((uint8_t*)recv_stage + off, (uint8_t*)&rx_buffers[i], rx_len[i]);
            off += rx_len[i];
        }

        recv_transaction = 0;
        long ret = deliver_frames(addr, length, num_packet, frLength,
                                  (const uint8_t*)recv_stage, poll_len);
        enable_preempt();
        return ret;
    }

    /*
     * Interrupt mode, first half: point the handler at the kernel staging
     * area, arm the descriptors and go to sleep.  XEmacPsRecvHandler() runs
     * with SUM cleared in whatever address space happens to be installed, so
     * it can only ever write into kernel memory.
     */
    _addr = (uintptr_t)recv_stage;
    _num_packet = num_packet;
    _frLength = recv_stage_len;
    EmacPsRecv(&EmacPsInstance, 0, num_packet);

    recv_waiter = current_running[cpu_id];
    /* handle_syscall() already advanced sepc past the `ecall` */
    regs_context_t *regs = (regs_context_t *)current_running[cpu_id]->kernel_sp;
    regs->sepc = regs->sepc - 4;

    do_block(&current_running[cpu_id]->list, &net_recv_queue);
    scheduler();
    enable_preempt();

    /* handle_syscall() writes this into a0, which is the very `addr` the
     * retried `ecall` picks up again */
    return (long)addr;
}

void do_net_send(uintptr_t addr, size_t length)
{
    // send all packet
    if(length > sizeof(EthernetFrame)){
        /* one call sends one frame, and tx_buffer is exactly that big */
        length = sizeof(EthernetFrame);
    }

    disable_preempt();

    /* the frame is read out of user memory before anything blocks, so the
     * caller's own page table is still installed here */
    prepare_user_range(addr, length);

    send_transaction = 1;
    memset(&tx_buffer, 0, sizeof(EthernetFrame));
    enable_sum();
    memcpy((uint8_t*)&tx_buffer, (uint8_t*)addr, (uint32_t)length);
    disable_sum();
    EmacPsSend(&EmacPsInstance, 0, length);

    if(net_poll_mode == 1){
        /*
         * XEmacPsSendHandler() wakes us up once the frame has left.  Nothing
         * happens after scheduler() -- the caller resumes in user mode right
         * after its `ecall`, by which time the send has completed -- so no
         * sepc rewind is needed here.
         */
        do_block(&current_running[cpu_id]->list, &net_send_queue);
        scheduler();
    }
    else{
        EmacPsWaitSend(&EmacPsInstance);
        send_transaction = 0;
    }

    enable_preempt();
}

void do_net_irq_mode(int mode)
{
    // turn on/off network driver's interrupt mode
    if(net_poll_mode != mode){
        assert(recv_transaction == 0);
        assert(send_transaction == 0);
        net_poll_mode = mode;
        if(net_poll_mode == 1){
            XEmacPs_IntEnable(&EmacPsInstance, (XEMACPS_IXR_TX_ERR_MASK | XEMACPS_IXR_RX_ERR_MASK |
                            (u32)XEMACPS_IXR_FRAMERX_MASK | (u32)XEMACPS_IXR_TXCOMPL_MASK));
            XEmacPs_WriteReg(EmacPsInstance.Config.BaseAddress, XEMACPS_IDR_OFFSET, 0);
        }
        else if(net_poll_mode == 0){
            XEmacPs_IntDisable(&EmacPsInstance, (XEMACPS_IXR_TX_ERR_MASK | XEMACPS_IXR_RX_ERR_MASK |
                            (u32)XEMACPS_IXR_FRAMERX_MASK | (u32)XEMACPS_IXR_TXCOMPL_MASK));
        }
    }
}
